using System;using System.Reflection;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class RoundPoolEdge{public static string Main(){EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");var c=Object.FindAnyObjectByType<BackyardForwardCourse>();var lip=c.flightStarts[2];var axis=c.flightDirections[2];var side=Vector3.Cross(Vector3.up,axis);float end=Racer.Editor.BackyardReverseAuthoring.Ground(lip+axis*9);typeof(Racer.Editor.BackyardReverseAuthoring).GetMethod("Sculpt",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{(Func<Vector3,bool>)(p=>{float a=Vector3.Dot(p-lip,axis);return a>-.3f&&a<9.01f&&Mathf.Abs(Vector3.Dot(p-lip,side))<5.3f;}),(Func<Vector3,Vector3>)(p=>{float a=Vector3.Dot(p-lip,axis),d=Mathf.Abs(Vector3.Dot(p-lip,side)),u=Mathf.Clamp01(a/9);float y=(2*u*u*u-3*u*u+1)*lip.y+(u*u*u-2*u*u+u)*9*.08f+(-2*u*u*u+3*u*u)*end+(u*u*u-u*u)*9*.12f;p.y=Mathf.Lerp(p.y,y,1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(2.7f,5.3f,d)));return p;}),"Rounded reduced takeoff release"});EditorSceneManager.MarkSceneDirty(c.gameObject.scene);EditorSceneManager.SaveScene(c.gameObject.scene);AssetDatabase.SaveAssets();File.WriteAllText("Docs/SevenCorrections/rounded-release.txt","Smoothed original vertical drop face for 9m beyond lip, retaining 0.08 launch grade and existing valley elevation; removes oblique vertical triangle contacts at high speed.");return "Rounded existing terrain release face";}}
